import{_ as t,o as e,c as r,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Keynote- Welcome to Cephalocon 2024 - Josh Durgin & Neha Ojha, IBM & Dan van der Ster, Clyso","description":"","frontmatter":{"title":"Keynote- Welcome to Cephalocon 2024 - Josh Durgin & Neha Ojha, IBM & Dan van der Ster, Clyso","date":"2025-01-23T00:00:00.000Z","updated":"2025-01-24T00:00:00.000Z","tags":["Ceph","Ceph conference","Distributed storage","Cloud computing","Storage technologies"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Keynote_-_Welcome_to_Cephalocon_2024_-_Josh_Durgin_Neha_Ojha_IBM_Dan_van_der_Ster_Clyso.md","filePath":"posts/2025/Keynote_-_Welcome_to_Cephalocon_2024_-_Josh_Durgin_Neha_Ojha_IBM_Dan_van_der_Ster_Clyso.md","lastUpdated":1780459816000}'),n={name:"posts/2025/Keynote_-_Welcome_to_Cephalocon_2024_-_Josh_Durgin_Neha_Ojha_IBM_Dan_van_der_Ster_Clyso.md"};function s(l,o,i,_,h,g){return e(),r("div",null,[...o[0]||(o[0]=[a('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>: Cephalocon 2024 开幕及 Ceph 相关活动介绍<br><strong>日期</strong>: 会议第一天<br><strong>主持人</strong>: Dan, Niha, Josh<br><strong>地点</strong>: CERN（欧洲核子研究中心）</p><h4 id="_1-会议开场及感谢" tabindex="-1">1. <strong>会议开场及感谢</strong> <a class="header-anchor" href="#_1-会议开场及感谢" aria-label="Permalink to &quot;1. **会议开场及感谢**&quot;">​</a></h4><ul><li><strong>主办方</strong>: 感谢 CERN 作为本次会议的主办方，为其提供的优越会议环境和设施。</li><li><strong>赞助商</strong>: 特别感谢白金赞助商 Bloomberg 和 IBM，以及黄金赞助商 klyo 和 waler，以及白银赞助商 42on 和 Canonical。</li><li><strong>会议安排</strong>: 会议分为两天，在 CERN 的两个建筑内进行。通过扫描 QR 码可以查看完整的会议日程。</li></ul><h4 id="_2-会议流程及活动安排" tabindex="-1">2. <strong>会议流程及活动安排</strong> <a class="header-anchor" href="#_2-会议流程及活动安排" aria-label="Permalink to &quot;2. **会议流程及活动安排**&quot;">​</a></h4><ul><li><strong>主会场</strong>: 主会场设在“Globe”，将进行 Keynote 演讲。</li><li><strong>分会场</strong>: 分会场设在主会场两侧，与会者可以根据日程选择参加不同的讨论会。</li><li><strong>赞助商展示区</strong>: 与会者可以在展示区与各公司代表进行交流，了解最新的技术动态。</li><li><strong>社交活动</strong>: 今晚 6 点到 7-30 将举行赞助商招待会，与会者可以领取两张饮品券。</li><li><strong>科学展览</strong>: 今天下午 5-30 到 7-00 将开放科学展览，特别为 SEFON 与会者准备。</li></ul><h4 id="_3-行为准则" tabindex="-1">3. <strong>行为准则</strong> <a class="header-anchor" href="#_3-行为准则" aria-label="Permalink to &quot;3. **行为准则**&quot;">​</a></h4><ul><li>会议强调尊重和包容的环境，与会者需遵守会议的行为准则。如有任何问题，可联系注册台。</li></ul><h4 id="_4-t-shirt-设计竞赛" tabindex="-1">4. <strong>T-shirt 设计竞赛</strong> <a class="header-anchor" href="#_4-t-shirt-设计竞赛" aria-label="Permalink to &quot;4. **T-shirt 设计竞赛**&quot;">​</a></h4><ul><li><strong>获奖者</strong>: Jason Bis（索尼互动娱乐）</li><li><strong>T-shirt 发放</strong>: 今晚在赞助商展示区可以领取。</li><li><strong>感谢</strong>: 感谢所有提交设计的人员，以及 L 基金会将设计转化为实际 T-shirt 的工作人员。</li></ul><h4 id="_5-cern-介绍" tabindex="-1">5. <strong>CERN 介绍</strong> <a class="header-anchor" href="#_5-cern-介绍" aria-label="Permalink to &quot;5. **CERN 介绍**&quot;">​</a></h4><ul><li><strong>演讲者</strong>: Enria Porcari（CERN IT 部门负责人）</li><li><strong>背景</strong>: Enria 在 CERN 工作了约三年，之前曾在世界粮食计划署担任 CIO。她将介绍 CERN 的 IT 基础设施及对本次会议的欢迎致辞。</li></ul><p><strong>后续行动计划</strong>:</p><ul><li>与会者需根据日程安排参加不同的讨论会和活动。</li><li>今晚 6 点到 7:30 参加赞助商招待会，领取 T-shirt 并参观科学展览。</li><li>遵守会议行为准则，确保会议顺利进行。</li></ul><p><strong>备注</strong>: Cephalocon 2024 是 Ceph 及相关分布式存储技术的盛会，与会者将有机会深入了解 Ceph 的最新进展及应用场景。</p>',15)])])}const u=t(n,[["render",s]]);export{d as __pageData,u as default};
